  line-height: var(--typography-microcopy-xs-line-height);
  letter-spacing: var(--typography-microcopy-xs-letter-spacing);
}
.typography-microcopy-md {
  font-family: var(--typography-microcopy-md-font-family);
  font-size: var(--typography-microcopy-md-font-size);
  font-weight: var(--typography-microcopy-md-font-weight);
  line-height: var(--typography-microcopy-md-line-height);
  letter-spacing: var(--typography-microcopy-md-letter-spacing);
}
.typography-body-sm {
  font-family: var(--typography-body-sm-font-family);
  font-size: var(--typography-body-sm-font-size);
  font-weight: var(--typography-body-sm-font-weight);
  line-height: var(--typography-body-sm-line-height);
  letter-spacing: var(--typography-body-sm-letter-spacing);
}
.typography-body-md {
  font-family: var(--typography-body-md-font-family);
  font-size: var(--typography-body-md-font-size);
  font-weight: var(--typography-body-md-font-weight);
  line-height: var(--typography-body-md-line-height);
  letter-spacing: var(--typography-body-md-letter-spacing);
}
.typography-heading-lg {
  font-family: var(--typography-heading-lg-font-family);
  font-size: var(--typography-heading-lg-font-size);
  font-weight: var(--typography-heading-lg-font-weight);
  line-height: var(--typography-heading-lg-line-height);
  letter-spacing: var(--typography-heading-lg-letter-spacing);
}
.typography-heading-md {
  font-family: var(--typography-heading-md-font-family);
  font-size: var(--typography-heading-md-font-size);
  font-weight: var(--typography-heading-md-font-weight);
  line-height: var(--typography-heading-md-line-height);
  letter-spacing: var(--typography-heading-md-letter-spacing);
}
.typography-meta {
  font-family: var(--typography-meta-font-family);
  font-size: var(--typography-meta-font-size);
  font-weight: var(--typography-meta-font-weight);
  line-height: var(--typography-meta-line-height);
  letter-spacing: var(--typography-meta-letter-spacing);
}
.typography-label-sm-strong {
  font-family: var(--typography-label-sm-strong-font-family);
  font-size: var(--typography-label-sm-strong-font-size);
  font-weight: var(--typography-label-sm-strong-font-weight);
  line-height: var(--typography-label-sm-strong-line-height);
  letter-spacing: var(--typography-label-sm-strong-letter-spacing);
}
.esa-alert-box {
  --_alert-bg: var(--color-background-utility-info-subtle, #fbfdff);
  --_alert-border: var(--color-border-utility-info, #acd8fc);
  --_alert-accent: var(--color-content-utility-info, #0d74ce);
  --_alert-icon-color: var(--_alert-accent);
  --_alert-title-color: var(--_alert-accent);
  --_alert-text-color: var(--alert-box-text-color, var(--color-content-default-secondary, #646464));
  display: flex;
  align-items: flex-start;
  gap: var(--spacing-300, 0.75rem);
  padding: var(--spacing-300, 0.75rem) var(--spacing-400, 1rem);
  border: var(--border-width-default, 1px) solid var(--_alert-border);
  border-radius: var(--radius-md, 0.5rem);
  background: var(--_alert-bg);
}
.esa-alert-box--danger {
  --_alert-bg: var(--color-background-utility-danger-subtle, #fffcfc);
  --_alert-border: var(--color-border-utility-danger, #fdbdbe);
  --_alert-accent: var(--color-content-utility-danger, #ce2c31);
}
.esa-alert-box__icon {
  flex-shrink: 0;
  color: var(--_alert-icon-color);
  padding-top: 1px;
}
.esa-alert-box__body {
  flex: 1;
  min-width: 0;
}
.esa-alert-box__title {
  display: block;
  color: var(--_alert-title-color);
  margin-bottom: var(--spacing-050, 0.125rem);
}
.esa-alert-box__message {
  color: var(--_alert-text-color);
}
.typography-microcopy-xs-strong {
  font-family: var(--typography-microcopy-xs-strong-font-family);
  font-size: var(--typography-microcopy-xs-strong-font-size);
  font-weight: var(--typography-microcopy-xs-strong-font-weight);
  line-height: var(--typography-microcopy-xs-strong-line-height);
  letter-spacing: var(--typography-microcopy-xs-strong-letter-spacing);
}
.typography-body-md {
  font-family: var(--typography-body-md-font-family);
  font-size: var(--typography-body-md-font-size);
  font-weight: var(--typography-body-md-font-weight);
  line-height: var(--typography-body-md-line-height);
  letter-spacing: var(--typography-body-md-letter-spacing);
}
.esa-button {
  --_btn-pad-y: var(--spacing-300, 0.75rem);
  --_btn-padding-x: var(--spacing-300, 0.75rem);
  --_btn-radius: var(--button-radius-md, 0.5rem);
  --_accent: var(--color-background-brand, #46a758);
  --_accent-hover: var(--color-background-brand-hover, #3e9b4f);
  --_on: var(--color-content-default-knockout, #fcfcfc);
  --_accent-text: var(--_accent);
  --_btn-tint-hover: color-mix(in srgb, var(--_accent) 8%, transparent);
  --_btn-tint-active: color-mix(in srgb, var(--_accent) 14%, transparent);
  display: inline-block;
}
.esa-button--sm {
  --_btn-pad-y: var(--spacing-250, 0.625rem);
  --_btn-padding-x: var(--spacing-250, 0.625rem);
  --_btn-radius: var(--button-radius-sm, 4px);
}
.esa-button__native {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--spacing-200, 8px);
  width: 100%;
  padding-block: var(--_btn-pad-y);
  padding-inline: var(--_btn-padding-x);
  border: var(--border-width-default, 1px) solid transparent;
  border-radius: var(--_btn-radius);
  text-decoration: none;
  cursor: pointer;
  transition:
    background var(--transition-fast, 0.15s ease),
    border-color var(--transition-fast, 0.15s ease);
  -webkit-appearance: none;
  appearance: none;
}
.esa-button--appearance-fill .esa-button__native {
  background: var(--_accent);
  color: var(--_on);
  border-color: var(--_accent-border, transparent);
}
.esa-button--variant-chrome .esa-button__native {
  background: transparent;
  color: inherit;
  border-color: transparent;
}
.esa-icon {
  --_icon-size: var(--icon-size-md, 20px);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: var(--_icon-size);
  height: var(--_icon-size);
  color: inherit;
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, 16px);
}
.esa-icon svg {
  display: block;
  width: var(--_icon-size);
  height: var(--_icon-size);
}
.esa-button__label {
  white-space: nowrap;
}
summary.esa-button {
  list-style: none;
  cursor: pointer;
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, 20px);
}
.esa-button--variant-secondary {
  --_accent: var(--color-background-brand-muted);
  --_accent-hover: var(--color-background-brand-muted-hover);
  --_on: var(--color-content-on-brand-muted, var(--color-content-default));
  --_accent-text: var(--color-content-brand);
  --_accent-border: var(--color-border-default-strong, #bbbbbb);
}
.esa-button--appearance-outline .esa-button__native,
.esa-button--appearance-dashed .esa-button__native {
  background: transparent;
  color: var(--_accent-text);
  border-color: var(--_accent);
}
.cbf-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  color: inherit;
}
.esa-nav-dropdown .esa-button__native > .esa-icon:last-child {
  transition: transform 0.15s ease;
}
.cbf-nav-link .cbf-icon {
  display: inline-flex;
  align-items: center;
}
.esa-pill {
  --_pill-bg: var(--color-background-elevation-sunken, #f0f0f0);
  --_pill-text: var(--color-content-default, #202020);
  --_pill-border: var(--color-border-default-subtle, #d9d9d9);
  --_pill-padding-y: var(--spacing-150, 0.375rem);
  --_pill-padding-x: var(--spacing-200, 0.5rem);
  --_pill-gap: var(--spacing-100, 0.25rem);
  display: inline-flex;
  align-items: center;
  gap: var(--_pill-gap);
  padding-block: var(--_pill-padding-y);
  padding-inline: var(--_pill-padding-x);
  border: var(--border-width-default, 1px) solid var(--_pill-border);
  border-radius: var(--radius-chip, var(--radius-sm, 0.25rem));
  background: var(--_pill-bg);
  color: var(--_pill-text);
  white-space: nowrap;
  box-sizing: border-box;
}
.esa-pill--sm {
  --_pill-padding-y: var(--spacing-100, 0.25rem);
  --_pill-padding-x: var(--spacing-150, 0.375rem);
}
.esa-pill--danger {
  --_pill-bg: var(--color-background-utility-danger-subtle, var(--color-red-2));
  --_pill-text: var(--color-content-utility-danger, #ce2c31);
  --_pill-border: var(--color-border-utility-danger, var(--color-red-6));
}
.esa-pill--warning {
  --_pill-bg: var(--color-background-utility-warning-subtle, var(--color-yellow-2));
  --_pill-text: var(--color-content-utility-warning, #ab6400);
  --_pill-border: var(--color-border-utility-warning, var(--color-yellow-6));
}
.stack {
  --gap: var(--spacing-400, 1rem);
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}
.esa-container {
  width: 100%;
  max-width: var(--_container-max, 1556px);
  margin-inline: auto;
  padding-inline: var(--spacing-600, 2rem);
}
.cbf-app-panel {
  display: flex;
  flex-direction: column;
  min-height: 80vh;
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  overflow: clip;
  background: var(--color-background-elevation-raised);
  box-shadow: 0 1px 3px color-mix(in srgb, var(--color-background-default-knockout) 8%, transparent);
}
.cbf-app-panel__crumb {
  background: var(--cbf-surface-crumb);
  border-bottom: 1px solid var(--color-border-default);
  padding: var(--spacing-400) var(--spacing-600);
}
.esa-breadcrumbs {
  --_crumb-link-color: var(--breadcrumbs-link-color, #646464);
  --_crumb-link-hover: var(--breadcrumbs-link-hover, #202020);
  --_crumb-current-color: var(--color-content-default, #202020);
  --_crumb-separator-color: var(--color-border-default-strong, #bbbbbb);
  --_crumb-gap: var(--spacing-200, 8px);
  display: block;
  background: var(--breadcrumbs-bg, transparent);
}
.cbf-app-panel__crumb .esa-breadcrumbs {
  --breadcrumbs-link-color: var(--color-content-default-secondary);
  --breadcrumbs-link-hover: var(--color-background-brand);
}
.esa-breadcrumbs__list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--_crumb-gap);
  list-style: none;
  margin: 0;
  padding: 0;
}
.esa-breadcrumbs__item {
  display: flex;
  align-items: center;
  gap: var(--_crumb-gap);
}
.esa-breadcrumbs__link {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100, 4px);
  color: var(--_crumb-link-color);
  text-decoration-color: transparent;
}
.esa-breadcrumbs__icon {
  display: inline-flex;
  align-items: center;
}
.esa-breadcrumbs__separator {
  flex-shrink: 0;
  color: var(--_crumb-separator-color);
}
.esa-breadcrumbs__current {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100, 4px);
  color: var(--_crumb-current-color);
}
.cbf-app-panel__body {
  flex: 1;
}
.cbf-app-panel__content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-400);
  padding: var(--spacing-600);
}
.esa-page-header {
  --_ph-title-color: var(--color-content-default, #202020);
  --_ph-title-font: var(
    --typography-heading-lg-font-family,
    var(--typography-font-family-display, "DM Sans", sans-serif)
  );
  --_ph-title-size: var(--typography-heading-lg-font-size, var(--font-size-600, 1.875rem));
  --_ph-title-weight: var(
    --typography-heading-lg-font-weight,
    var(--typography-font-weight-semibold, 550)
  );
  --_ph-eyebrow-color: var(--color-content-default-secondary, #646464);
  --_ph-eyebrow-size: var(--typography-label-md-font-size, var(--font-size-200, 0.9375rem));
  --_ph-gap: var(--spacing-200, 0.5rem);
  --_ph-bar-gap: var(--spacing-500, 1.5rem);
  --_ph-crumb-gap: var(--spacing-300, 0.75rem);
  display: block;
  background: transparent;
}
.esa-page-header__bar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--_ph-bar-gap);
  flex-wrap: wrap;
}
.esa-page-header__titles {
  display: flex;
  flex-direction: column;
  gap: var(--_ph-gap);
  min-width: 0;
}
.esa-page-header__eyebrow {
  display: flex;
  align-items: center;
  gap: var(--spacing-100, 0.25rem);
  margin: 0;
  font-size: var(--_ph-eyebrow-size);
  color: var(--_ph-eyebrow-color);
}
.esa-page-header__title {
  margin: 0;
  font-family: var(--_ph-title-font);
  font-size: var(--_ph-title-size);
  font-weight: var(--_ph-title-weight);
  color: var(--_ph-title-color);
}
.repel {
  --gap: var(--spacing-400, 1rem);
  --align: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--gap);
  align-items: var(--align);
  justify-content: space-between;
}
.cluster {
  --gap: var(--spacing-300, 0.75rem);
  --align: center;
  --justify: flex-start;
  display: flex;
  flex-wrap: wrap;
  gap: var(--gap);
  align-items: var(--align);
  justify-content: var(--justify);
}
.cbf-page {
  padding-block: var(--spacing-600) var(--spacing-800);
}
.cbf-mywork-tabs__panel {
  min-width: 0;
}
.cbf-task-queue__head {
  align-items: baseline;
  gap: var(--spacing-400, 1rem);
  flex-wrap: wrap;
}
.cbf-task-queue__count {
  color: var(--color-content-default-tertiary, #737373);
  white-space: nowrap;
}
.cbf-task-queue__list {
  margin: 0;
  padding: 0;
  list-style: none;
  border-top: 1px solid var(--color-border-default-subtle, #e5e5e5);
}
.cbf-task-queue__row {
  display: flex;
  align-items: center;
  gap: var(--spacing-300, 0.75rem);
  padding-block: var(--spacing-300, 0.75rem);
  padding-inline: var(--spacing-200, 0.5rem);
  border-bottom: 1px solid var(--color-border-default-subtle, #e5e5e5);
  min-height: 52px;
}
.cbf-task-queue__body {
  flex: 1 1 0;
  min-width: 0;
}
.cbf-task-queue__what {
  font-weight: var(--typography-font-weight-medium, 500);
  color: var(--color-content-default, #171717);
  font-size: var(--type-body-size, 14px);
  line-height: 1.4;
}
.cbf-task-queue__meta {
  color: var(--color-content-default-tertiary, #737373);
  line-height: 1.3;
}
.cbf-task-queue__due,
.cbf-task-queue__action {
  flex-shrink: 0;
}
.cbf-task-queue__row--waiting {
  opacity: 0.65;
}
.cbf-task-queue__waiting-label {
  flex-shrink: 0;
  color: var(--color-content-default-tertiary, #737373);
  font-style: italic;
  white-space: nowrap;
}
.cbf-task-risk-band {
  padding-block: var(--spacing-400);
  border-top: 1px solid var(--color-border-default);
}
.cbf-task-risk-band__heading {
  margin: 0;
  color: var(--color-content-default);
}
.cbf-task-risk-band__list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.cbf-task-risk-band__row {
  --align: flex-start;
  padding-block: var(--spacing-200);
  border-bottom: 1px solid var(--color-border-default-subtle);
}
.cbf-task-risk-band__pill-wrap {
  flex-shrink: 0;
  padding-top: 2px;
  min-width: 7rem;
}
.cbf-task-risk-band__body {
  flex: 1;
  min-width: 0;
}
.cbf-task-risk-band__title {
  font-weight: 500;
  color: var(--color-content-default);
}
.cbf-task-risk-band__detail {
  color: var(--color-content-default-secondary);
}
.cbf-task-risk-band__meta {
  color: var(--color-content-default-tertiary);
}
.cbf-task-risk-band__row:last-child {
  border-bottom: none;
}

full.css:
:root,
[data-theme="cb-fish"] {
  --alert-box-text-color: #525252;
  --animation-overlay-enter: 0.25s ease-out;
  --border-width-default: 1px;
  --breadcrumbs-bg: transparent;
  --breadcrumbs-link-color: #525252;
  --breadcrumbs-link-hover: #3d3d3d;
  --button-radius-md: 0.5rem;
  --button-radius-sm: 0.25rem;
  --cbf-surface-crumb: #f4f4f4;
  --color-background-brand: #1e5386;
  --color-background-brand-hover: #1a4570;
  --color-background-brand-muted: #2770b2;
  --color-background-brand-muted-hover: #1e5386;
  --color-background-default-knockout: #13273e;
  --color-background-elevation-raised: #fcfcfc;
  --color-background-elevation-sunken: #f3f7fc;
  --color-background-utility-danger-subtle: #fffcfc;
  --color-background-utility-info-subtle: #f3f7fc;
  --color-background-utility-warning-subtle: #fefdfb;
  --color-border-default: #dcdcdc;
  --color-border-default-strong: #bdbdbd;
  --color-border-default-subtle: #efefef;
  --color-border-utility-danger: #fdbdbe;
  --color-border-utility-info: #c6dcf1;
  --color-border-utility-warning: #f3d673;
  --color-content-brand: #1e5386;
  --color-content-default: #3d3d3d;
  --color-content-default-knockout: #fcfcfc;
  --color-content-default-secondary: #525252;
  --color-content-default-tertiary: #656565;
  --color-content-link: #1e5386;
  --color-content-on-brand-muted: #203c25;
  --color-content-utility-danger: #ce2c31;
  --color-content-utility-info: #0d74ce;
  --color-content-utility-warning: #ab6400;
  --color-red-2: #fff7f7;
  --color-red-6: #fdbdbe;
  --color-yellow-2: #fefbe9;
  --color-yellow-6: #f3d673;
  --elevation-1: 0 1px 4px 0 rgba(0, 0, 0, 0.03);
  --elevation-5: 0 8px 32px -8px rgba(0, 0, 0, 0.08);
  --font-size-150: clamp(0.6875rem, 0.61rem + 0.38vw, 0.875rem);
  --font-size-200: clamp(0.75rem, 0.66rem + 0.44vw, 0.9375rem);
  --font-size-600: clamp(1.375rem, 1.2rem + 0.88vw, 1.875rem);
  --icon-size-md: 20px;
  --icon-size-sm: 16px;
  --link-column-rule-color: color-mix(in srgb, currentColor 40%, transparent);
  --radius-100: 0.25rem;
  --radius-chip: 0.25rem;
  --radius-md: 0.5rem;
  --radius-pill: 9999px;
  --radius-sm: 0.25rem;
  --side-dialog-inset: 16px;
  --side-dialog-width: 400px;
  --side-dialog-width-sm: 320px;
  --spacing-050: 0.125rem;
  --spacing-100: 0.25rem;
  --spacing-150: 0.375rem;
  --spacing-200: 0.5rem;
  --spacing-250: 0.625rem;
  --spacing-300: 0.75rem;
  --spacing-400: 1rem;
  --spacing-500: 1.5rem;
  --spacing-600: 2rem;
  --spacing-800: 4rem;
  --tab-layout-height-lg: 52px;
  --tab-layout-height-md: 44px;
  --transition-fast: 0.15s ease;
  --typography-body-md-font-family: "IBM Plex Sans", sans-serif;
  --typography-body-md-font-size: clamp(0.75rem, 0.66rem + 0.44vw, 0.9375rem);
  --typography-body-md-font-weight: 400;
  --typography-body-md-letter-spacing: 0.01em;
  --typography-body-md-line-height: 1.6;
  --typography-body-sm-font-family: "IBM Plex Sans", sans-serif;
  --typography-body-sm-font-size: clamp(0.6875rem, 0.61rem + 0.38vw, 0.875rem);
  --typography-body-sm-font-weight: 400;
  --typography-body-sm-letter-spacing: 0.01em;
  --typography-body-sm-line-height: 1.6;
  --typography-font-family-display: "IBM Plex Sans Condensed", "IBM Plex Sans", sans-serif;
  --typography-font-family-sans: "IBM Plex Sans", sans-serif;
  --typography-font-weight-medium: 500;
  --typography-font-weight-semibold: 600;
  --typography-heading-lg-font-family: "IBM Plex Sans Condensed", "IBM Plex Sans", sans-serif;
  --typography-heading-lg-font-size: clamp(1.375rem, 1.2rem + 0.88vw, 1.875rem);
  --typography-heading-lg-font-weight: 600;
  --typography-heading-lg-letter-spacing: -0.01em;
  --typography-heading-lg-line-height: 1.3;
  --typography-heading-md-font-family: "IBM Plex Sans Condensed", "IBM Plex Sans", sans-serif;
  --typography-heading-md-font-size: clamp(1.125rem, 0.98rem + 0.72vw, 1.5rem);
