  list-style: none;
  cursor: pointer;
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, 20px);
}
.esa-button--variant-secondary {
  --_accent: var(--color-background-brand-muted);
  --_accent-hover: var(--color-background-brand-muted-hover);
  --_on: var(--color-content-on-brand-muted, var(--color-content-default));
  --_accent-text: var(--color-content-brand);
  --_accent-border: var(--color-border-default-strong, #bbbbbb);
}
.esa-button--appearance-outline .esa-button__native,
.esa-button--appearance-dashed .esa-button__native {
  background: transparent;
  color: var(--_accent-text);
  border-color: var(--_accent);
}
.cbf-app-bar--admin .esa-app-bar__row {
  display: grid;
  grid-template-columns: 1fr minmax(0, 380px) 1fr;
}
.cbf-app-bar--admin .esa-app-bar__start {
  justify-self: start;
}
.cbf-nav-collapsible {
  display: contents;
}
.cbf-app-bar--admin .esa-app-bar__main {
  justify-content: center;
}
.cbf-omni-trigger {
  display: flex;
  align-items: center;
  gap: var(--spacing-200);
  width: 380px;
  max-width: 100%;
  padding: 5px var(--spacing-200) 5px var(--spacing-300);
  background: #ffffff1a;
  border: 1px solid rgba(255, 255, 255, 0.22);
  border-radius: 999px;
  color: #ffffffbf;
  transition:
    background 0.12s,
    border-color 0.12s;
}
.cbf-app-bar--admin .cbf-omni-trigger {
  min-width: 0;
}
.cbf-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
  color: inherit;
}
.cbf-omni-trigger__ph {
  flex: 1;
  min-width: 0;
  text-align: left;
  font-size: 13px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.cbf-omni-trigger__kbd {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 5px;
  font-family: var(--typography-font-family-sans);
  font-size: 13px;
  font-weight: var(--typography-font-weight-medium);
  color: #ffffffd9;
  background: #ffffff1f;
  border: 1px solid rgba(255, 255, 255, 0.25);
  border-radius: 4px;
}
.cbf-app-bar--admin .esa-app-bar__end {
  justify-self: end;
}
.esa-nav-dropdown {
  position: relative;
}
.esa-nav-dropdown .esa-button__native > .esa-icon:last-child {
  transition: transform 0.15s ease;
}
.cbf-nav-burger {
  display: none;
}
.cbf-logo {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-300, 12px);
  flex: none;
  color: inherit;
  text-decoration: none;
}
.cbf-logo__mark {
  width: 48px;
  height: 48px;
  flex: none;
}
.cbf-logo__type {
  height: 40px;
  width: auto;
}
.cbf-nav-actions {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-600);
}
.cbf-nav-link {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  color: inherit;
  background: none;
  border: 0;
  font-size: 16px;
  font-weight: var(--typography-font-weight-medium);
  white-space: nowrap;
}
.cbf-nav-link .cbf-icon {
  display: inline-flex;
  align-items: center;
}
.cbf-nav-link--user {
  position: relative;
  padding-left: var(--spacing-500);
}
.cbf-nav-link--user:before {
  content: "";
  position: absolute;
  left: 0;
  top: 50%;
  transform: translateY(-50%);
  width: 1px;
  height: 1.1em;
  background: #ffffff40;
}
.cbf-omni {
  position: fixed;
  inset: 0;
  z-index: 80;
}
.cbf-omni[hidden] {
  display: none;
}
.esa-pill {
  --_pill-bg: var(--color-background-elevation-sunken, #f0f0f0);
  --_pill-text: var(--color-content-default, #202020);
  --_pill-border: var(--color-border-default-subtle, #d9d9d9);
  --_pill-padding-y: var(--spacing-150, 0.375rem);
  --_pill-padding-x: var(--spacing-200, 0.5rem);
  --_pill-gap: var(--spacing-100, 0.25rem);
  display: inline-flex;
  align-items: center;
  gap: var(--_pill-gap);
  padding-block: var(--_pill-padding-y);
  padding-inline: var(--_pill-padding-x);
  border: var(--border-width-default, 1px) solid var(--_pill-border);
  border-radius: var(--radius-chip, var(--radius-sm, 0.25rem));
  background: var(--_pill-bg);
  color: var(--_pill-text);
  white-space: nowrap;
  box-sizing: border-box;
}
.esa-pill--sm {
  --_pill-padding-y: var(--spacing-100, 0.25rem);
  --_pill-padding-x: var(--spacing-150, 0.375rem);
}
.esa-pill--danger {
  --_pill-bg: var(--color-background-utility-danger-subtle, var(--color-red-2));
  --_pill-text: var(--color-content-utility-danger, #ce2c31);
  --_pill-border: var(--color-border-utility-danger, var(--color-red-6));
}
.esa-pill--warning {
  --_pill-bg: var(--color-background-utility-warning-subtle, var(--color-yellow-2));
  --_pill-text: var(--color-content-utility-warning, #ab6400);
  --_pill-border: var(--color-border-utility-warning, var(--color-yellow-6));
}
.esa-app-bar {
  --_bar-gap: var(--spacing-600, 32px);
  --_bar-pad-x: var(--spacing-600, 32px);
  --_bar-pad-y: var(--spacing-400, 16px);
  display: block;
  width: 100%;
  background: var(--color-background-elevation-raised, #fcfcfc);
  color: var(--color-content-default, #202020);
}
.esa-app-bar--brand-strong {
  background: var(--color-background-default-knockout, #202020);
  color: var(--color-content-default-knockout, #fcfcfc);
}
.esa-app-bar__row {
  display: flex;
  align-items: center;
  gap: var(--_bar-gap);
  padding: var(--_bar-pad-y) var(--_bar-pad-x);
}
.esa-app-bar__start,
.esa-app-bar__main,
.esa-app-bar__end {
  display: inline-flex;
  align-items: center;
  gap: var(--_bar-gap);
}
.esa-app-bar__start {
  flex: none;
}
.esa-app-bar__main {
  flex: 1 1 auto;
  min-width: 0;
}
.esa-app-bar__end {
  flex: none;
  margin-left: auto;
}
.esa-app-bar--brand {
  background: var(--color-background-brand, #46a758);
  color: var(--color-content-default-knockout, #fcfcfc);
}
.stack {
  --gap: var(--spacing-400, 1rem);
  display: flex;
  flex-direction: column;
  gap: var(--gap);
}
[data-gap="lg"] {
  --gap: var(--spacing-500, 1.5rem);
}
:where(h1, h2, h3, h4, h5, h6, p, figure, blockquote, dl, dd, ul, ol, pre) {
  margin: 0;
}
.esa-container {
  width: 100%;
  max-width: var(--_container-max, 1556px);
  margin-inline: auto;
  padding-inline: var(--spacing-600, 2rem);
}
.cbf-app-panel {
  display: flex;
  flex-direction: column;
  min-height: 80vh;
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  overflow: clip;
  background: var(--color-background-elevation-raised);
  box-shadow: 0 1px 3px color-mix(in srgb, var(--color-background-default-knockout) 8%, transparent);
}
.cbf-app-panel__crumb {
  background: var(--cbf-surface-crumb);
  border-bottom: 1px solid var(--color-border-default);
  padding: var(--spacing-400) var(--spacing-600);
}
.esa-breadcrumbs {
  --_crumb-link-color: var(--breadcrumbs-link-color, #646464);
  --_crumb-link-hover: var(--breadcrumbs-link-hover, #202020);
  --_crumb-current-color: var(--color-content-default, #202020);
  --_crumb-separator-color: var(--color-border-default-strong, #bbbbbb);
  --_crumb-gap: var(--spacing-200, 8px);
  display: block;
  background: var(--breadcrumbs-bg, transparent);
}
.cbf-app-panel__crumb .esa-breadcrumbs {
  --breadcrumbs-link-color: var(--color-content-default-secondary);
  --breadcrumbs-link-hover: var(--color-background-brand);
}
.esa-breadcrumbs__list {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--_crumb-gap);
  list-style: none;
  margin: 0;
  padding: 0;
}
.esa-breadcrumbs__item {
  display: flex;
  align-items: center;
  gap: var(--_crumb-gap);
}
.esa-breadcrumbs__link {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100, 4px);
  color: var(--_crumb-link-color);
  text-decoration-color: transparent;
}
.esa-breadcrumbs__icon {
  display: inline-flex;
  align-items: center;
}
.esa-breadcrumbs__separator {
  flex-shrink: 0;
  color: var(--_crumb-separator-color);
}
.esa-breadcrumbs__current {
  display: inline-flex;
  align-items: center;
  gap: var(--spacing-100, 4px);
  color: var(--_crumb-current-color);
}
.cbf-app-panel__body {
  flex: 1;
}
.cbf-app-panel__content {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: var(--spacing-400);
  padding: var(--spacing-600);
}
.esa-page-header {
  --_ph-title-color: var(--color-content-default, #202020);
  --_ph-title-font: var(
    --typography-heading-lg-font-family,
    var(--typography-font-family-display, "DM Sans", sans-serif)
  );
  --_ph-title-size: var(--typography-heading-lg-font-size, var(--font-size-600, 1.875rem));
  --_ph-title-weight: var(
    --typography-heading-lg-font-weight,
    var(--typography-font-weight-semibold, 550)
  );
  --_ph-eyebrow-color: var(--color-content-default-secondary, #646464);
  --_ph-eyebrow-size: var(--typography-label-md-font-size, var(--font-size-200, 0.9375rem));
  --_ph-gap: var(--spacing-200, 0.5rem);
  --_ph-bar-gap: var(--spacing-500, 1.5rem);
  --_ph-crumb-gap: var(--spacing-300, 0.75rem);
  display: block;
  background: transparent;
}
.esa-page-header__bar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--_ph-bar-gap);
  flex-wrap: wrap;
}
.esa-page-header__titles {
  display: flex;
  flex-direction: column;
  gap: var(--_ph-gap);
  min-width: 0;
}
.esa-page-header__eyebrow {
  display: flex;
  align-items: center;
  gap: var(--spacing-100, 0.25rem);
  margin: 0;
  font-size: var(--_ph-eyebrow-size);
  color: var(--_ph-eyebrow-color);
}
.esa-page-header__title {
  margin: 0;
  font-family: var(--_ph-title-font);
  font-size: var(--_ph-title-size);
  font-weight: var(--_ph-title-weight);
  color: var(--_ph-title-color);
}
[data-gap="md"] {
  --gap: var(--spacing-400, 1rem);
}
.repel {
  --gap: var(--spacing-400, 1rem);
  --align: center;
  display: flex;
  flex-wrap: wrap;
  gap: var(--gap);
  align-items: var(--align);
  justify-content: space-between;
}
[data-gap="xs"] {
  --gap: var(--spacing-200, 0.5rem);
}
[data-gap="sm"] {
  --gap: var(--spacing-300, 0.75rem);
}
.cluster {
  --gap: var(--spacing-300, 0.75rem);
  --align: center;
  --justify: flex-start;
  display: flex;
  flex-wrap: wrap;
  gap: var(--gap);
  align-items: var(--align);
  justify-content: var(--justify);
}
.cbf-page {
  padding-block: var(--spacing-600) var(--spacing-800);
}
.cbf-mywork-tabs__panel {
  min-width: 0;
}
esa-tab-layout:not(:defined) > [slot^="panel-"] {
  display: none;
}
.cbf-task-queue__head {
  align-items: baseline;
  gap: var(--spacing-400, 1rem);
  flex-wrap: wrap;
}
.cbf-task-queue__count {
  color: var(--color-content-default-tertiary, #737373);
  white-space: nowrap;
}
.cbf-task-queue__list {
  margin: 0;
  padding: 0;
  list-style: none;
  border-top: 1px solid var(--color-border-default-subtle, #e5e5e5);
}
.cbf-task-queue__row {
  display: flex;
  align-items: center;
  gap: var(--spacing-300, 0.75rem);
  padding-block: var(--spacing-300, 0.75rem);
  padding-inline: var(--spacing-200, 0.5rem);
  border-bottom: 1px solid var(--color-border-default-subtle, #e5e5e5);
  min-height: 52px;
}
.cbf-task-queue__body {
  flex: 1 1 0;
  min-width: 0;
}
.cbf-task-queue__what {
  font-weight: var(--typography-font-weight-medium, 500);
  color: var(--color-content-default, #171717);
  font-size: var(--type-body-size, 14px);
  line-height: 1.4;
}
.cbf-task-queue__meta {
  color: var(--color-content-default-tertiary, #737373);
  line-height: 1.3;
}
.cbf-task-queue__due,
.cbf-task-queue__action {
  flex-shrink: 0;
}
.cbf-task-queue__row--waiting {
  opacity: 0.65;
}
.cbf-task-queue__waiting-label {
  flex-shrink: 0;
  color: var(--color-content-default-tertiary, #737373);
  font-style: italic;
  white-space: nowrap;
}
.cbf-task-risk-band {
  padding-block: var(--spacing-400);
  border-top: 1px solid var(--color-border-default);
}
.cbf-task-risk-band__heading {
  margin: 0;
  color: var(--color-content-default);
}
.cbf-task-risk-band__list {
  list-style: none;
  padding: 0;
  margin: 0;
}
.cbf-task-risk-band__row {
  --align: flex-start;
  padding-block: var(--spacing-200);
  border-bottom: 1px solid var(--color-border-default-subtle);
}
.cbf-task-risk-band__pill-wrap {
  flex-shrink: 0;
  padding-top: 2px;
  min-width: 7rem;
}
.cbf-task-risk-band__body {
  flex: 1;
  min-width: 0;
}
.cbf-task-risk-band__title {
  font-weight: 500;
  color: var(--color-content-default);
}
.cbf-task-risk-band__detail {
  color: var(--color-content-default-secondary);
}
.cbf-task-risk-band__meta {
  color: var(--color-content-default-tertiary);
}
.cbf-task-risk-band__row:last-child {
  border-bottom: none;
}
